         nEntriesThisGeneration = 0;
         nGeneration++;
         if (nGeneration == 4) {
@@ -210,10 +227,10 @@ void CRollingBloomFilter::insert(std::span<const unsigned char> vKey)
             data[p + 1] = p2 & mask;
